spec.query:
from(bucket: "${bucket_raw}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "thermal_resistance")
  |> filter(fn: (r) => r.dev_idx =~ /${device:regex}/)
  |> filter(fn: (r) => 
      r._field == "r_factor" or 
      r._field == "indoor_start_c" or 
      r._field == "outdoor_avg_c"
  )
  |> drop(columns: ["hvac_mode"]) 
  |> pivot(rowKey:["_time"], columnKey: ["_field"], valueColumn: "_value")

  |> filter(fn: (r) => exists r.r_factor and exists r.indoor_start_c and exists r.outdoor_avg_c)

  // CALCULATED MATH FILTER: Compute Delta T early to apply strict thermodynamic filtering
  |> map(fn: (r) => ({
      r with
      delta_t: r.indoor_start_c - r.outdoor_avg_c
  }))

  // FIX 1: Ignore low-delta shoulder noise where math breaks down (|Delta T| must be > 4°C)
  // FIX 2: Lock R-factors to physically possible boundaries (0 to 60)
  //|> filter(fn: (r) => (r.delta_t > 4.0 or r.delta_t < -4.0))
  |> filter(fn: (r) => r.r_factor > 0.0 and r.r_factor < 60.0)

  |> map(fn: (r) => ({
      _time: r._time,
      dev_idx: r.dev_idx,
      delta_t: r.delta_t,
      r_factor: r.r_factor
  }))
  |> group(columns: ["dev_idx"])
  |> sort(columns: ["_time"])

options.script:
const series = Array.isArray(data?.series) ? data.series : [];
if (series.length === 0) return { data: [], layout: {} };

const vectorToArray = (values) => {
  if (values == null) return [];
  if (Array.isArray(values)) return values;
  if (Array.isArray(values.buffer)) return values.buffer;
  if (typeof values.toArray === 'function') return values.toArray();
  if (typeof values.length === 'number') {
    const out = [];
    for (let i = 0; i < values.length; i += 1) {
      out.push(typeof values.get === 'function' ? values.get(i) : values[i]);
    }
    return out;
  }
  return [];
};

const calculateMedian = (arr) => {
  if (arr.length === 0) return null;
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
};

const calculateStdDev = (arr, mean) => {
  if (arr.length <= 1) return 0;
  const variance = arr.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0) / arr.length;
  return Math.sqrt(variance);
};

const traces = [];
const heatingRFactors = [];
const coolingRFactors = [];
const allHeatDeltaT = [];
const allCoolDeltaT = [];

// Track device label across loops
let globalDevLabel = '';

series.forEach((frame, frameIdx) => {
  const fields = frame?.fields || [];
  const fDeltaT = fields.find(f => f.name === 'delta_t');
  const fRFactor = fields.find(f => f.name === 'r_factor');
  const fDev = fields.find(f => f.name === 'dev_idx');

  // Dynamic device label identification matching layout parsing rules
  const rawDevVals = fDev ? vectorToArray(fDev.values) : [];
  let devLabel = rawDevVals.length > 0 && rawDevVals[0] != null ? String(rawDevVals[0]) : '';
  if (!devLabel) {
    const match = frame.name ? frame.name.match(/dev_idx=["']?(\w+)/) : null;
    devLabel = match ? match[1] : String(frameIdx);
  }
  if (devLabel && !globalDevLabel) globalDevLabel = devLabel;

  if (!fDeltaT || !fRFactor) return;

  const rawDeltaT = vectorToArray(fDeltaT.values);
  const rawRFactor = vectorToArray(fRFactor.values);

  const deltaT_Heating = [];
  const rFactor_Heating = [];
  const deltaT_Cooling = [];
  const rFactor_Cooling = [];

  for (let i = 0; i < rawDeltaT.length; i++) {
    const dt = Number(rawDeltaT[i]);
    const rf = Number(rawRFactor[i]);
    if (Number.isFinite(dt) && Number.isFinite(rf)) {
      if (dt > 0) {
        heatingRFactors.push(rf);
        allHeatDeltaT.push(dt);
        deltaT_Heating.push(dt);
        rFactor_Heating.push(rf);
      } else {
        coolingRFactors.push(rf);
        allCoolDeltaT.push(dt);
        deltaT_Cooling.push(dt);
        rFactor_Cooling.push(rf);
      }
    }
  }

  // Add Heating Scatter Points
  if (rFactor_Heating.length > 0) {
    traces.push({
      x: deltaT_Heating,
      y: rFactor_Heating,
      name: `Dev ${devLabel} | Heat Obs`,
      type: 'scatter',
      mode: 'markers',
      marker: { color: '#ef6c00', size: 6, opacity: 0.5, symbol: 'triangle-up' },
      hovertemplate: `Heating R-Value: <b>%{y:.2f}</b><extra></extra>`
    });
  }

  // Add Cooling Scatter Points
  if (rFactor_Cooling.length > 0) {
    traces.push({
      x: deltaT_Cooling,
      y: rFactor_Cooling,
      name: `Dev ${devLabel} | Cool Obs`,
      type: 'scatter',
      mode: 'markers',
      marker: { color: '#1565c0', size: 5.5, opacity: 0.5, symbol: 'circle' },
      hovertemplate: `Cooling R-Value: <b>%{y:.2f}</b><extra></extra>`
    });
  }
});

const finalDevStr = globalDevLabel || '0';

// Dynamically size X-axis & baseline/variance spans to full observed heating and cooling ΔT ranges
const maxHeatX = allHeatDeltaT.length > 0
  ? Math.max(15, Math.ceil((Math.max(...allHeatDeltaT) + 0.5) / 5) * 5)
  : 15;
const minCoolX = allCoolDeltaT.length > 0
  ? Math.min(-15, Math.floor((Math.min(...allCoolDeltaT) - 0.5) / 5) * 5)
  : -15;

// --- HEATING METRICS & SHADING AREA ---
const medianHeatingR = calculateMedian(heatingRFactors);
if (medianHeatingR !== null) {
  const heatingMean = heatingRFactors.reduce((a, b) => a + b, 0) / heatingRFactors.length;
  const heatingStdDev = calculateStdDev(heatingRFactors, heatingMean);
  const heatLow = Math.max(0, medianHeatingR - heatingStdDev);
  const heatHigh = Math.min(60, medianHeatingR + heatingStdDev);

  traces.push({
    x: [0, maxHeatX, maxHeatX, 0],
    y: [heatHigh, heatHigh, heatLow, heatLow],
    fill: 'toself',
    fillcolor: 'rgba(239, 108, 0, 0.08)',
    line: { color: 'transparent' },
    name: `Dev ${finalDevStr} | Heat Variance (±${heatingStdDev.toFixed(1)} R)`,
    type: 'scatter',
    hoverinfo: 'skip'
  });

  traces.push({
    x: [0, maxHeatX],
    y: [medianHeatingR, medianHeatingR],
    name: `Dev ${finalDevStr} | Heat Baseline R-${medianHeatingR.toFixed(1)}`,
    type: 'scatter',
    mode: 'lines',
    line: { color: '#ef6c00', width: 2.5, dash: 'dashdot' },
    hovertemplate: `Median Heating R: <b>%{y:.2f}</b><extra></extra>`
  });
}

// --- COOLING METRICS & SHADING AREA ---
const medianCoolingR = calculateMedian(coolingRFactors);
if (medianCoolingR !== null) {
  const coolingMean = coolingRFactors.reduce((a, b) => a + b, 0) / coolingRFactors.length;
  const coolingStdDev = calculateStdDev(coolingRFactors, coolingMean);
  const coolLow = Math.max(0, medianCoolingR - coolingStdDev);
  const coolHigh = Math.min(60, medianCoolingR + coolingStdDev);

  traces.push({
    x: [minCoolX, 0, 0, minCoolX],
    y: [coolHigh, coolHigh, coolLow, coolLow],
    fill: 'toself',
    fillcolor: 'rgba(21, 101, 192, 0.08)',
    line: { color: 'transparent' },
    name: `Dev ${finalDevStr} | Cool Variance (±${coolingStdDev.toFixed(1)} R)`,
    type: 'scatter',
    hoverinfo: 'skip'
  });

  traces.push({
    x: [minCoolX, 0],
    y: [medianCoolingR, medianCoolingR],
    name: `Dev ${finalDevStr} | Cool Baseline R-${medianCoolingR.toFixed(1)}`,
    type: 'scatter',
    mode: 'lines',
    line: { color: '#1565c0', width: 2.5, dash: 'dashdot' },
    hovertemplate: `Median Cooling R: <b>%{y:.2f}</b><extra></extra>`
  });
}

return {
  data: traces,
  layout: {
    margin: { l: 60, r: 40, t: 40, b: 60 },
    hovermode: 'x unified',
    hoverlabel: {
      bgcolor: '#111217',
      bordercolor: '#2c2c35',
      font: { color: '#cccccc', family: 'Inter, sans-serif', size: 12 }
    },
    plot_bgcolor: 'rgba(0,0,0,0)',
    paper_bgcolor: 'rgba(0,0,0,0)',
    font: { color: '#cccccc', family: 'Inter, sans-serif' },
    xaxis: {
      type: 'linear',
      autorange: false,
      range: [minCoolX, maxHeatX],
      dtick: 5,
      title: { text: 'Indoor - Outdoor Temperature Delta (ΔT °C)', font: { size: 12 } },
      gridcolor: '#222225',
      zeroline: true,
      zerolinecolor: '#3e3e42'
    },
    yaxis: {
      type: 'linear',
      autorange: false,
      range: [-0.5, 60],
      title: { text: 'Effective Structural Thermal Resistance (R-Factor)', font: { size: 12 } },
      gridcolor: '#222225',
      zeroline: false
    },
    legend: { orientation: 'h', y: -0.25, x: 0.5, xanchor: 'center' }
  }
};

const series = Array.isArray(data?.series) ? data.series : [];
if (series.length === 0) return { data: [], layout: {} };

const vectorToArray = (values) => {
  if (values == null) return [];
  if (Array.isArray(values)) return values;
  if (Array.isArray(values.buffer)) return values.buffer;
  if (typeof values.toArray === 'function') return values.toArray();
  if (typeof values.length === 'number') {
    const out = [];
    for (let i = 0; i < values.length; i += 1) {
      out.push(typeof values.get === 'function' ? values.get(i) : values[i]);
    }
    return out;
  }
  return [];
};

const percentile = (sorted, p) => {
  if (!sorted.length) return 0;
  const idx = Math.min(sorted.length - 1, Math.max(0, Math.floor(sorted.length * p)));
  return sorted[idx];
};

let activeUnit = 'F';
if (typeof variables !== 'undefined' && variables.temp_unit) {
  activeUnit = typeof variables.temp_unit === 'object' ? String(variables.temp_unit.value || 'F') : String(variables.temp_unit);
}
const isF = activeUnit === 'F';

const deviceColors = ['#1565c0', '#2e7d32', '#ef6c00', '#6a1b9a', '#c62828', '#00838f'];
const trendColors = ['#d32f2f', '#388e3c', '#f57c00', '#8e24aa', '#e53935', '#0097a7'];

const traces = [];
const allCleanY = [];

series.forEach((frame, frameIdx) => {
  const fields = frame?.fields || [];
  const deltaTFields = fields.filter(f => f.name.startsWith('delta_t'));

  deltaTFields.forEach((fDeltaT) => {
    const match = fDeltaT.name.match(/\d+$/);
    const suffix = match ? match[0] : '';

    const rateName = suffix ? `recovery_rate ${suffix}` : 'recovery_rate';
    const fRate = fields.find(f => f.name === rateName);

    if (!fRate) return;

    let devLabel = suffix;
    if (!devLabel) {
      const fDev = fields.find(f => f.name === 'dev_idx');
      const rawDevVals = fDev ? vectorToArray(fDev.values) : [];
      devLabel = rawDevVals.length > 0 && rawDevVals[0] != null ? String(rawDevVals[0]) : String(frameIdx);
    }

    const rawX = vectorToArray(fDeltaT.values);
    const rawRate = vectorToArray(fRate.values);
    const maxRate = isF ? 8.1 : 4.5;

    const xData = [];
    const yRate = [];

    for (let i = 0; i < rawX.length; i++) {
      const xv = Number(rawX[i]);
      const yv = Number(rawRate[i]);
      if (Number.isFinite(xv) && Number.isFinite(yv) && yv > 0 && yv <= maxRate) {
        xData.push(xv);
        yRate.push(yv);
        allCleanY.push(yv);
      }
    }

    if (yRate.length === 0) return;

    const colorIdx = parseInt(devLabel, 10) % deviceColors.length || 0;
    const mColor = deviceColors[colorIdx];
    const tColor = trendColors[colorIdx];

    // Trace 1: Performance Scatter Points
    traces.push({
      x: xData,
      y: yRate,
      name: `Dev ${devLabel} Recovery`,
      type: 'scatter',
      mode: 'markers',
      marker: {
        color: mColor,
        size: 5.5,
        opacity: 0.55,
        line: { color: '#000000', width: 0.3 }
      },
      hovertemplate: `Dev ${devLabel} Actual: <b>%{y:.2f}°${activeUnit}/h</b><extra></extra>`
    });

    // Trace 2: IQR-trimmed Linear Regression Curve (immune to residual cycle spikes)
    if (yRate.length >= 2) {
      const ySorted = [...yRate].sort((a, b) => a - b);
      const q1 = percentile(ySorted, 0.25);
      const q3 = percentile(ySorted, 0.75);
      const iqr = Math.max(q3 - q1, isF ? 0.5 : 0.3);
      const loFence = q1 - 2.0 * iqr;
      const hiFence = q3 + 2.0 * iqr;

      let sx = 0, sy = 0, sxy = 0, sx2 = 0, n = 0;
      for (let i = 0; i < xData.length; i++) {
        if (yRate[i] < loFence || yRate[i] > hiFence) continue;
        sx += xData[i];
        sy += yRate[i];
        sxy += xData[i] * yRate[i];
        sx2 += xData[i] * xData[i];
        n += 1;
      }

      const den = n * sx2 - sx * sx;
      if (n >= 2 && den !== 0) {
        const m = (n * sxy - sx * sy) / den;
        const b = (sy - m * sx) / n;

        const xSorted = [...xData].sort((a, b) => a - b);
        const minX = xSorted[0];
        const maxX = xSorted[xSorted.length - 1];

        const operatorStr = b >= 0 ? '+' : '-';
        const absoluteB = Math.abs(b);
        const equationLabel = `Dev ${devLabel}: Rate = (${m.toFixed(3)}*ΔT) ${operatorStr} ${absoluteB.toFixed(2)}`;

        traces.push({
          x: [minX, maxX],
          y: [m * minX + b, m * maxX + b],
          name: equationLabel,
          type: 'scatter',
          mode: 'lines',
          line: { color: tColor, width: 2.5, dash: 'solid' },
          hovertemplate: `Dev ${devLabel} Model: <b>%{y:.2f}°${activeUnit}/h</b><extra></extra>`
        });
      }
    }
  });
});

let yMax = isF ? 6.0 : 3.5;
if (allCleanY.length > 0) {
  const sortedY = [...allCleanY].sort((a, b) => a - b);
  const p98 = percentile(sortedY, 0.98);
  yMax = Math.min(isF ? 8.5 : 5.0, Math.max(isF ? 4.0 : 2.5, Math.ceil((p98 + (isF ? 0.75 : 0.4)) * 2) / 2));
}

return {
  data: traces,
  layout: {
    margin: { l: 60, r: 40, t: 40, b: 60 },
    hovermode: 'x unified',
    hoverlabel: {
      bgcolor: '#111217',
      bordercolor: '#2c2c35',
      font: { color: '#cccccc', family: 'Inter, sans-serif', size: 12 }
    },
    plot_bgcolor: 'rgba(0,0,0,0)',
    paper_bgcolor: 'rgba(0,0,0,0)',
    font: { color: '#cccccc', family: 'Inter, sans-serif' },
    xaxis: {
      type: 'linear',
      title: { text: `Indoor - Outdoor Temperature Delta (ΔT °${activeUnit})`, font: { size: 12 } },
      gridcolor: '#222225',
      zeroline: true,
      zerolinecolor: '#3e3e42'
    },
    yaxis: {
      type: 'linear',
      autorange: false,
      range: [0, yMax],
      title: { text: `Thermal Recovery Rate (°${activeUnit} / Hour)`, font: { size: 12 } },
      gridcolor: '#222225',
      zeroline: true,
      zerolinecolor: '#3a3a39'
    },
    legend: { orientation: 'h', y: -0.25, x: 0.5, xanchor: 'center' }
  }
};

const series = Array.isArray(data?.series) ? data.series : [];
if (series.length === 0) return { data: [], layout: {} };

const vectorToArray = (values) => {
  if (values == null) return [];
  if (Array.isArray(values)) return values;
  if (Array.isArray(values.buffer)) return values.buffer;
  if (typeof values.toArray === 'function') return values.toArray();
  if (typeof values.length === 'number') {
    const out = [];
    for (let i = 0; i < values.length; i += 1) {
      out.push(typeof values.get === 'function' ? values.get(i) : values[i]);
    }
    return out;
  }
  return [];
};

let activeUnit = 'F'; 
if (typeof variables !== 'undefined' && variables.temp_unit) {
  activeUnit = typeof variables.temp_unit === 'object' ? String(variables.temp_unit.value || 'F') : String(variables.temp_unit);
}

const stageConfig = {
  'heating_stage1_time':  { name: 'Heat S1', color: '#c62828', trend: '#b71c1c' },
  'heating_stage2_time':  { name: 'Heat S2', color: '#ef5350', trend: '#e53935' },
  'cooling_stage1_time':  { name: 'Cool S1', color: '#1565c0', trend: '#0d47a1' },
  'cooling_stage2_time':  { name: 'Cool S2', color: '#42a5f5', trend: '#1e88e5' },
  'alt_heat_stage1_time': { name: 'Alt Heat S1', color: '#ef6c00', trend: '#e65100' },
  'alt_heat_stage2_time': { name: 'Alt Heat S2', color: '#ffb300', trend: '#ff8f00' }
};

const traces = [];

series.forEach((frame, frameIdx) => {
  const fields = frame?.fields || [];
  const fTemp = fields.find(f => f.name.startsWith('avg_outdoor_temp_c'));
  const fDev = fields.find(f => f.name === 'dev_idx');

  const rawDevVals = fDev ? vectorToArray(fDev.values) : [];
  let devLabel = rawDevVals.length > 0 && rawDevVals[0] != null ? String(rawDevVals[0]) : '';
  if (!devLabel) {
    const match = frame.name ? frame.name.match(/dev_idx=["']?(\w+)/) : null;
    devLabel = match ? match[1] : String(frameIdx);
  }

  if (!fTemp) return;
  const rawTemp = vectorToArray(fTemp.values);

  Object.keys(stageConfig).forEach((stageField) => {
    const fRuntime = fields.find(f => f.name.startsWith(stageField));
    if (!fRuntime) return;

    const rawRuntime = vectorToArray(fRuntime.values);
    const xData = [];
    const yData = [];

    for (let i = 0; i < rawTemp.length; i++) {
      if (rawTemp[i] != null && rawRuntime[i] != null && rawRuntime[i] > 0.01) {
        xData.push(Number(rawTemp[i]));
        yData.push(Number(rawRuntime[i]));
      }
    }

    if (xData.length > 0) {
      const cfg = stageConfig[stageField];
      const isStage2 = stageField.includes('stage2');

      // Trace 1: Granular Stage Scatter Points (Clean Label)
      traces.push({
        x: xData,
        y: yData,
        name: `Dev ${devLabel} | ${cfg.name}`,
        type: 'scatter',
        mode: 'markers',
        marker: { 
          color: cfg.color, 
          size: isStage2 ? 6.5 : 5.5, 
          opacity: 0.6,
          symbol: isStage2 ? 'triangle-up' : 'circle'
        },
        hovertemplate: `Dev ${devLabel} | ${cfg.name} Actual: <b>%{y:.2f} h</b><extra></extra>`
      });

      // Trace 2: Independent Linear Regression Curve
      if (xData.length >= 2) {
        let sx = 0, sy = 0, sxy = 0, sx2 = 0;
        const n = xData.length;
        for (let i = 0; i < n; n, i++) {
          sx += xData[i];
          sy += yData[i];
          sxy += xData[i] * yData[i];
          sx2 += xData[i] * xData[i];
        }

        const den = n * sx2 - sx * sx;
        if (den !== 0) {
          const m = (n * sxy - sx * sy) / den;
          const b = (sy - m * sx) / n;

          const xSorted = [...xData].sort((a, b) => a - b);
          const minX = xSorted[0];
          const maxX = xSorted[xSorted.length - 1];

          const sign = b >= 0 ? '+' : '-';
          const equationLabel = `Dev ${devLabel} | ${cfg.name}: h = ${m.toFixed(3)}T ${sign} ${Math.abs(b).toFixed(1)}`;

          traces.push({
            x: [minX, maxX],
            y: [m * minX + b, m * maxX + b],
            name: equationLabel,
            type: 'scatter',
            mode: 'lines',
            line: { 
              color: cfg.trend, 
              width: 2.5, 
              dash: isStage2 ? 'dash' : 'solid' 
            },
            hovertemplate: `Dev ${devLabel} | ${cfg.name} Model: <b>%{y:.2f} h</b><extra></extra>`
          });
        }
      }
    }
  });
});

return {
  data: traces,
  layout: {
    margin: { l: 60, r: 40, t: 40, b: 60 },
    hovermode: 'x unified', 
    hoverlabel: {
      bgcolor: '#111217',
      bordercolor: '#2c2c35',
      font: { color: '#cccccc', family: 'Inter, sans-serif', size: 12 }
    },
    plot_bgcolor: 'rgba(0,0,0,0)',
    paper_bgcolor: 'rgba(0,0,0,0)',
    font: { color: '#cccccc', family: 'Inter, sans-serif' },
    xaxis: {
      type: 'linear',
      title: { text: `Average Daily Outdoor Temperature (°${activeUnit})`, font: { size: 12 } },
      gridcolor: '#222225',
      zeroline: false
    },
    yaxis: {
      type: 'linear',
      autorange: false,
      range: [-0.4, 7.0], 
      title: { text: 'Daily Stage Runtime (Hours)', font: { size: 12 } },
      gridcolor: '#222225',
      zeroline: true,
      zerolinecolor: '#3a3a39'
    },
    legend: { orientation: 'h', y: -0.25, x: 0.5, xanchor: 'center' }
  }
};

spec.query:
from(bucket: "${bucket_model}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "computed_metrics")
  |> filter(fn: (r) => r.dev_idx =~ /${device:regex}/)
  |> filter(fn: (r) => r.cadence == "1d")
  |> filter(fn: (r) =>
      r._field == "heating_cycle_count" or
      r._field == "cooling_cycle_count" or
      r._field == "fan_cycle_count" or
      r._field == "humidifier_cycle_count")

  // 1. Group by time to line up all distinct cycle fields for the same day
  |> group(columns: ["_time"])

  // 2. Pivot fields into columns so we can perform cross-field subtraction
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")

  // 3. Subtract active cooling/heating calls from total fan cycles to isolate standalone fan runs
  |> map(fn: (r) => {
      hc = if exists r.heating_cycle_count then r.heating_cycle_count else 0.0
      cc = if exists r.cooling_cycle_count then r.cooling_cycle_count else 0.0

      total_hvac_cycles = hc + cc
      raw_fan_cycles = if exists r.fan_cycle_count then r.fan_cycle_count else 0.0

      // Isolate cycles where the fan ran strictly on its own without heating or cooling
      fan_only_cycles = if raw_fan_cycles > total_hvac_cycles then raw_fan_cycles - total_hvac_cycles else 0.0

      return {
        _time: r._time,
        heating_cycle_count: r.heating_cycle_count,
        cooling_cycle_count: r.cooling_cycle_count,
        humidifier_cycle_count: r.humidifier_cycle_count,
        fan_cycle_count: fan_only_cycles // Overwritten with standalone circulation cycles
      }
  })

  // 4. Merge back into a clean stream for Grafana stacked bar engine
  |> group()
  |> sort(columns: ["_time"])

