}

const vectorToArray = (values) => {
  if (values == null) return [];
  if (Array.isArray(values)) return values;
  if (Array.isArray(values.buffer)) return values.buffer;
  if (typeof values.toArray === 'function') return values.toArray();
  if (typeof values.length === 'number') {
    const out = [];
    for (let i = 0; i < values.length; i += 1) {
      out.push(typeof values.get === 'function' ? values.get(i) : values[i]);
    }
    return out;
  }
  return [];
};

const fieldByName = (fields, name) => fields.find((f) => f.name === name);

const medianOf = (arr) => {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 !== 0 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};

const weightedMedian = (pairs) => {
  if (!pairs.length) return null;
  const sorted = [...pairs].sort((a, b) => a.y - b.y);
  let totalW = 0;
  for (let i = 0; i < sorted.length; i += 1) totalW += sorted[i].w;
  if (totalW <= 0) return null;
  const half = totalW / 2;
  let acc = 0;
  for (let i = 0; i < sorted.length; i += 1) {
    acc += sorted[i].w;
    if (acc >= half) return sorted[i].y;
  }
  return sorted[sorted.length - 1].y;
};

const rows = [];
for (const frame of series) {
  const fields = frame && Array.isArray(frame.fields) ? frame.fields : [];
  const fx = fieldByName(fields, 'x');
  const fy = fieldByName(fields, 'y');
  const fstage = fieldByName(fields, 'stage');
  const fdev = fieldByName(fields, '_dev_idx');

  if (!fx || !fy || !fstage || !fdev) continue;

  const xs = vectorToArray(fx.values);
  const ys = vectorToArray(fy.values);
  const stages = vectorToArray(fstage.values);
  const devs = vectorToArray(fdev.values);
  const n = Math.min(xs.length, ys.length, stages.length, devs.length);

  for (let i = 0; i < n; i += 1) {
    const x = Number(xs[i]);
    const y = Number(ys[i]);
    const stage = String(stages[i] || '');
    const dev = String(devs[i] || '');
    if (Number.isFinite(x) && Number.isFinite(y) && stage && dev && stage !== 'other') {
      rows.push({ x, y, stage, dev });
    }
  }
}

if (rows.length === 0) {
  return {
    data: [{ type: 'scatter', mode: 'markers', x: [], y: [] }],
    layout: {}
  };
}

const palette = {
  'heat_stage1': '#c62828',
  'heat_stage2': '#ef5350',
  'alt_heat_stage1': '#ef6c00',
  'alt_heat_stage2': '#ffb300',
  'cool_stage1': '#1565c0',
  'cool_stage2': '#42a5f5',
  'fan': '#2e7d32',
  'humidifier': '#00897b'
};

const labelMap = {
  'heat_stage1': 'Heat 1 Δ',
  'heat_stage2': 'Heat 2 Δ',
  'alt_heat_stage1': 'Aux Heat 1 Δ',
  'alt_heat_stage2': 'Aux Heat 2 Δ',
  'cool_stage1': 'Cool 1 Δ',
  'cool_stage2': 'Cool 2 Δ',
  'fan': 'Fan Δ',
  'humidifier': 'Humidifier Δ'
};

let activeUnit = 'F';
if (typeof variables !== 'undefined' && variables.temp_unit) {
  activeUnit = typeof variables.temp_unit === 'object' ? String(variables.temp_unit.value || 'F') : String(variables.temp_unit);
}

const isF = activeUnit === 'F';
const yMultiplier = isF ? 1.8 : 1.0;

const groups = {};
for (const r of rows) {
  const cleanStage = r.stage.replace('delta_deg_c_per_hr_', '');
  const key = `${cleanStage}|${r.dev}`;
  if (!groups[key]) {
    groups[key] = { stage: cleanStage, dev: r.dev, x: [], y: [] };
  }
  groups[key].x.push(r.x);
  groups[key].y.push(r.y * yMultiplier);
}

const traces = [];
const keys = Object.keys(groups).sort();

const xAxisMin = isF ? -10 : -25;
const xAxisMax = isF ? 100 : 40;
const xStep = isF ? 0.5 : 0.25;
const span = isF ? 8.0 : 4.5;
const maxPhysicalRate = isF ? 8.0 : 4.5;

const allTrendY = [];

for (const key of keys) {
  const g = groups[key];
  const color = palette[g.stage] || '#9ca3af';
  const stageLabel = labelMap[g.stage] || g.stage.replace(/_/g, ' ');
  const label = `Dev ${g.dev} | ${stageLabel}`;

  const combined = g.x.map((x, i) => ({ x, y: g.y[i] }));
  combined.sort((a, b) => a.x - b.x);
  const sortedX = combined.map(p => p.x);
  const sortedY = combined.map(p => p.y);

  const isStage2 = g.stage.includes('stage2');

  // Trace 1: Scatter Points
  traces.push({
    type: 'scatter',
    mode: 'markers',
    name: label,
    x: sortedX,
    y: sortedY,
    marker: {
      color: color,
      size: isStage2 ? 5.5 : 4.5,
      opacity: 0.2,
      symbol: isStage2 ? 'triangle-up' : 'circle'
    },
    showlegend: true,
    hoverinfo: 'skip'
  });

  // Trace 2: Outlier-Resistant 2-Pass Robust LOWESS (Weighted Median + Tukey Bisquare)
  // Pre-filter extreme short-cycle glitches (|rate| > 8 °F/hr) before smoothing
  const cleanPts = combined.filter((p) => Math.abs(p.y) <= maxPhysicalRate);
  if (cleanPts.length >= 4) {
    const cx = cleanPts.map((p) => p.x);
    const cy = cleanPts.map((p) => p.y);

    // Pass 1: Local tricube-weighted median at each observed point
    const absRes = new Array(cx.length);
    for (let i = 0; i < cx.length; i += 1) {
      const xi = cx[i];
      const localPairs = [];
      for (let j = 0; j < cx.length; j += 1) {
        const dist = Math.abs(cx[j] - xi);
        if (dist < span) {
          const w = Math.pow(1 - Math.pow(dist / span, 3), 3);
          if (w > 0) localPairs.push({ y: cy[j], w });
        }
      }
      const wm = weightedMedian(localPairs);
      absRes[i] = Math.abs(cy[i] - (wm !== null ? wm : cy[i]));
    }

    // Tukey bisquare robustness weights from MAD residual scale
    const mad = medianOf(absRes);
    const scale = Math.max(mad * 6.0, isF ? 1.5 : 0.85);
    const rWeights = absRes.map((res) => {
      const u = res / scale;
      return u < 1 ? Math.pow(1 - u * u, 2) : 0;
    });

    const minObserved = Math.max(xAxisMin, Math.floor(cx[0]));
    const maxObserved = Math.min(xAxisMax, Math.ceil(cx[cx.length - 1]));

    const denseX = [];
    const denseY = [];

    for (let x = minObserved; x <= maxObserved + 1e-9; x += xStep) {
      let totalWeight = 0;
      let weightedSumY = 0;
      let supportCount = 0;

      for (let i = 0; i < cx.length; i += 1) {
        const rw = rWeights[i];
        if (rw <= 0) continue;
        const dist = Math.abs(cx[i] - x);
        if (dist < span) {
          const w = Math.pow(1 - Math.pow(dist / span, 3), 3) * rw;
          if (w > 0) {
            weightedSumY += cy[i] * w;
            totalWeight += w;
            supportCount += 1;
          }
        }
      }

      // Require >= 4 supporting points so sparse edge tails don't plunge wildly
      if (totalWeight > 0.35 && supportCount >= 4) {
        const yVal = Number((weightedSumY / totalWeight).toFixed(2));
        denseX.push(Number(x.toFixed(2)));
        denseY.push(yVal);
        allTrendY.push(yVal);
      }
    }

    if (denseX.length >= 2) {
      traces.push({
        type: 'scatter',
        mode: 'lines',
        name: `${label} Trend`,
        x: denseX,
        y: denseY,
        line: {
          color: color,
          width: 3,
          dash: isStage2 ? 'dash' : 'solid'
        },
        opacity: 0.95,
        hovertemplate: `<span style="color:${color}">▲</span> ${stageLabel}: <b>%{y:+.2f} °${activeUnit}/h</b><extra></extra>`
      });
    }
  }
}

// Dynamic Y-axis bounds sized to show both Cooling and Heating trendlines cleanly
let yMin = isF ? -3.0 : -1.75;
let yMax = isF ? 5.5 : 3.25;
if (allTrendY.length > 0) {
  const minTrend = Math.min(...allTrendY);
  const maxTrend = Math.max(...allTrendY);
  const pad = isF ? 1.0 : 0.5;
  const hardMin = isF ? -6.0 : -3.5;
  const hardMax = isF ? 8.0 : 4.5;
  yMin = Math.max(hardMin, Math.min(yMin, Math.floor((minTrend - pad) * 2) / 2));
  yMax = Math.min(hardMax, Math.max(yMax, Math.ceil((maxTrend + pad) * 2) / 2));
}

// Vertical Staging Threshold Delimiters
const cutoffLines = isF
  ? [{ x: 65 }, { x: 75 }, { x: 85 }, { x: 95 }]
  : [{ x: 18 }, { x: 24 }, { x: 30 }, { x: 35 }];
const shapes = cutoffLines.map(line => ({
  type: 'line',
  x0: line.x,
  x1: line.x,
  y0: yMin,
  y1: yMax,
  xref: 'x',
  yref: 'y',
  line: {
    color: '#343438',
    width: 2,
    dash: 'dash'
  }
}));

return {
  data: traces,
  layout: {
    margin: { l: 65, r: 40, t: 40, b: 60 },
    hovermode: 'x unified',
    hoverlabel: {
      bgcolor: '#111217',
      bordercolor: '#2c2c35',
      font: { color: '#cccccc', family: 'Inter, sans-serif', size: 12 },
      namelength: 0
    },
    plot_bgcolor: 'rgba(0,0,0,0)',
    paper_bgcolor: 'rgba(0,0,0,0)',
    font: { color: '#cccccc' },
    shapes: shapes,
    xaxis: {
      type: 'linear',
      autorange: false,
      range: [xAxisMin, xAxisMax],
      tickmode: 'linear',
      tick0: xAxisMin,
      dtick: 5,
      title: { text: `Outdoor Temperature (°${activeUnit})`, font: { size: 13 } },
      gridcolor: '#222225',
      zeroline: false,
      hoverformat: '.1f'
    },
    yaxis: {
      type: 'linear',
      autorange: false,
      range: [yMin, yMax],
      title: { text: `Thermal Rate of Change (Δ°${activeUnit} / hr)`, font: { size: 13 } },
      gridcolor: '#222225',
      zeroline: true,
      zerolinecolor: '#3a3a39',
      zerolinewidth: 1.5
    },
    legend: {
      orientation: 'h',
      y: -0.25,
      x: 0.5,
      xanchor: 'center',
      font: { size: 11 }
    }
  }
};
